package com.pranit.productsupport.core.api;
import com.pranit.productsupport.contracts.CreatePaymentResponse;import com.pranit.productsupport.core.domain.Payment;import com.pranit.productsupport.core.service.PaymentService;import com.pranit.productsupport.core.service.PaymentTransactionService;import org.springframework.context.annotation.Profile;import org.springframework.http.HttpStatus;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1") public class PaymentController {private final PaymentService service;public PaymentController(PaymentService s){service=s;}@PostMapping("/quotes/{quoteId}/payment") @ResponseStatus(HttpStatus.CREATED) public CreatePaymentResponse create(@AuthenticationPrincipal Jwt jwt,@PathVariable Long quoteId){return service.create(quoteId,Long.valueOf(jwt.getSubject()));}}
@RestController @Profile("local") @RequestMapping("/internal/v1/dev/payments") class MockPaymentController {private final PaymentTransactionService tx;private final com.pranit.productsupport.core.repository.PaymentRepository repo;MockPaymentController(PaymentService s,com.pranit.productsupport.core.repository.PaymentRepository r){tx=s.transaction();repo=r;}@PostMapping("/{id}/capture") public java.util.Map<String,Object> capture(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){Payment p=tx.captureMock(id,Long.valueOf(jwt.getSubject()));return java.util.Map.of("paymentId",p.getId(),"status",p.getStatus(),"provider",p.getProvider());}}
